import{_ as a,c as i,a0 as t,o as s}from"./chunks/framework.B6JXc2q-.js";const u=JSON.parse('{"title":"播放控制模型","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/playback-control-model.md","filePath":"architecture/playback-control-model.md"}'),o={name:"architecture/playback-control-model.md"};function l(n,e,d,c,r,p){return s(),i("div",null,e[0]||(e[0]=[t(`<h1 id="播放控制模型" tabindex="-1">播放控制模型 <a class="header-anchor" href="#播放控制模型" aria-label="Permalink to &quot;播放控制模型&quot;">​</a></h1><p>版本：v1.1 状态：现行（迁移中） 最后更新：2026-11-22</p><p>本文描述<strong>当前代码</strong>的播放队列、随机会话与上一首/下一首控制边界（服务端逐首下发）。</p><blockquote><p><strong>迁移说明</strong>：<a href="./../adr/0007-speaker-owned-queue.html">ADR-0007</a> 已确定改为“音箱持有播放队列，服务端跟随”，正在分步实施（第 1–3 步已完成：队列下发见第 5 节）。第 1、4 节的意图边界（UI 只发意图、next/previous 不重建队列、随机只洗一次）在新架构中继续有效；第 2、4、5 节中关于计时器、<code>_play_list_items</code> 和设备导航方法的内容会在对应步骤完成时改写。新增代码按 ADR-0007 的组件划分写，不要再往本文描述的逐首路径上叠加机制。</p></blockquote><hr><h2 id="_1-核心不变量" tabindex="-1">1. 核心不变量 <a class="header-anchor" href="#_1-核心不变量" aria-label="Permalink to &quot;1. 核心不变量&quot;">​</a></h2><ol><li><code>music_library</code> 是歌单成员事实的权威来源。</li><li>每台设备的 <code>XiaoMusicDevice</code> 是当前运行时播放队列快照、当前索引与播放 session 的唯一权威。</li><li>WebUI、Home Assistant 与第三方调用方只发送播放意图，不计算下一首或上一首的曲目 ID。</li><li>正常的 next/previous 只移动当前队列索引，不重新解析歌单、不重建队列、不重新洗牌。</li><li>新播放请求可以建立新 session；控制请求不得隐式建立新 session。</li><li>音箱上报状态用于确认投递和完成状态，不得反向改写随机队列顺序。</li></ol><hr><h2 id="_2-状态归属" tabindex="-1">2. 状态归属 <a class="header-anchor" href="#_2-状态归属" aria-label="Permalink to &quot;2. 状态归属&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>权威</th><th>说明</th></tr></thead><tbody><tr><td>歌单成员事实</td><td><code>music_library</code></td><td>提供结构化 membership 与 entity record</td></tr><tr><td>当前设备队列快照</td><td><code>XiaoMusicDevice._play_list_items</code></td><td>session 内稳定，不随 next/previous 重建</td></tr><tr><td>当前索引</td><td><code>XiaoMusicDevice._current_index</code></td><td>next/previous 的唯一位置指针</td></tr><tr><td>当前播放 session</td><td><code>XiaoMusicDevice._play_session_id</code></td><td>仅作为 async media session invalidation id，使旧 timer、确认任务和异步回调失效；不承担 queue/command/attempt 语义</td></tr><tr><td>runtime phase / lifecycle</td><td><code>PlaybackRuntimeState</code> + <code>LifecycleToken</code></td><td>runtime phase 是播放状态权威；token 拆分 queue session、command generation、track attempt</td></tr><tr><td>异步播放任务</td><td><code>PlaybackTaskRegistry</code></td><td>每类任务唯一 owner；retry 不允许裸 <code>asyncio.create_task</code></td></tr><tr><td>持久播放模式</td><td><code>device.play_type</code></td><td>用户设备偏好，例如随机、全部循环、单曲循环</td></tr><tr><td>单次随机请求</td><td><code>PlayOptions.shuffle</code></td><td>只影响本次新 session，不修改 <code>device.play_type</code></td></tr><tr><td>播放状态投影</td><td><code>PlaybackFacade.build_player_state_snapshot()</code></td><td>对外只读投影，不拥有队列</td></tr></tbody></table><p><code>_play_list_items</code> 是从 <code>music_library</code> 建立的运行时快照，不是第二份歌单事实库。歌单内容变化仍由 <code>music_library</code> 管理；当前播放 session 是否保持旧顺序由 <code>XiaoMusicDevice</code> 决定。</p><hr><h2 id="_3-新随机会话" tabindex="-1">3. 新随机会话 <a class="header-anchor" href="#_3-新随机会话" aria-label="Permalink to &quot;3. 新随机会话&quot;">​</a></h2><p>正式入口：</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/play</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;device_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;device_id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;playlist_name&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source_hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;options&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;shuffle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>建立过程：</p><ol><li><code>PlaybackFacade</code> 从歌单 membership 选择起始成员，并根据 entity record 推断来源。</li><li><code>PlaybackCoordinator</code> 解析媒体并通过 transport 投递。</li><li><code>XiaoMusicDevice.on_external_url_play()</code> 建立新的播放 session。</li><li><code>XiaoMusicDevice</code> 从 <code>music_library</code> 复制当前歌单成员，生成设备运行时队列快照。</li><li>当 <code>options.shuffle=true</code> 或设备持久模式为随机时，只在该新 session 建立时洗牌一次。</li><li>当前曲目被定位到该快照中的真实索引。</li></ol><p>随机语义是“稳定的打乱队列”，不是每次 next 时随机抽取一首歌。</p><hr><h2 id="_4-next-previous-单一控制链" tabindex="-1">4. next/previous 单一控制链 <a class="header-anchor" href="#_4-next-previous-单一控制链" aria-label="Permalink to &quot;4. next/previous 单一控制链&quot;">​</a></h2><p>手动 next 的正式调用链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WebUI / 外部调用方</span></span>
<span class="line"><span>  → POST /api/v1/control/next</span></span>
<span class="line"><span>  → PlaybackFacade.next</span></span>
<span class="line"><span>  → PlaybackCoordinator.next</span></span>
<span class="line"><span>  → TransportRouter</span></span>
<span class="line"><span>  → MinaTransport</span></span>
<span class="line"><span>  → XiaoMusicDevice._play_next(manual=True)</span></span>
<span class="line"><span>  → current_index + 1</span></span>
<span class="line"><span>  → 播放队列快照中的目标曲目</span></span></code></pre></div><p>previous 同理，最终进入 <code>XiaoMusicDevice._play_prev(manual=True)</code>。</p><p>自动完成路径也必须汇入同一个设备导航入口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>next timer 到期</span></span>
<span class="line"><span>  → 提交 AUTO_NEXT（reason=timer_track_end）</span></span>
<span class="line"><span>  → XiaoMusicDevice._play_next(manual=False, auto_advance=True)</span></span></code></pre></div><h3 id="禁止行为" tabindex="-1">禁止行为 <a class="header-anchor" href="#禁止行为" aria-label="Permalink to &quot;禁止行为&quot;">​</a></h3><p>WebUI 点击 next/previous 时不得：</p><ul><li>根据当前页面歌曲数组自行计算目标曲目；</li><li>先调用 <code>POST /api/v1/play</code> 播放目标曲目；</li><li>在 next/previous 后重新发送歌单名；</li><li>重新建立或重新洗牌播放队列；</li><li>直接依赖音箱原生队列决定 xiaomusic session 的下一首。</li></ul><p><code>POST /api/v1/play</code> 表达“建立或替换播放 session”；<code>POST /api/v1/control/next</code> 表达“在当前 session 中向前移动”。两者不得混用。</p><hr><h2 id="_5-播放完成与失败" tabindex="-1">5. 播放完成与失败 <a class="header-anchor" href="#_5-播放完成与失败" aria-label="Permalink to &quot;5. 播放完成与失败&quot;">​</a></h2><ul><li><code>get_offset_duration()</code> 是纯查询，不得触发切歌或创建任务。</li><li><strong>队列下发</strong>（ADR-0007 第 3 步，2026-11-23 起，支持 music API 的型号）：歌单曲目按窗口一次下发（默认 20 首），音箱自己切歌；StreamGateway 收到音箱拉取某一项时，服务端把当前曲目切到该项（<code>follow_track</code>）。窗口放完时音箱拉取静音哨兵，服务端以下一首为起点下发新窗口。此时 next timer 只做兜底，在预期结束后 8 s 才触发；单曲循环不设 timer。</li><li>逐首路径（不支持 music API 的型号、<code>queue_window_size=0</code>、没有歌单上下文的单独链接、网关不处理的地址）：自动完成判定只在 next timer 到期路径执行；到期后<strong>直接</strong>推进下一首，不再查询音箱状态（2026-11-22 起：音箱在循环单项队列时总报告 playing，查询只会推迟切歌）。</li><li>自动切歌不先停止（2026-11-23 起固定，<code>auto_next_preplay_stop</code> 已删除）；手动操作和新播放仍先停止。</li><li>顺序播放到歌单末尾时停止，不回到开头；单曲播放到期即停止。</li><li><strong>开播确认</strong>（ADR-0007 第 4 步）：经 StreamGateway 下发的曲目，以音箱拉取起始项作为开播确认，此后才进入 PLAYING，开播时间取拉流时间；<code>START_FETCH_TIMEOUT_SEC</code>（15 s）内未拉流按播放失败交给失败策略。网关不处理的地址（电台、站点中转）下发成功即视为开播。不再轮询音箱状态（<code>player_get_status</code>），也不再有 Jellyfin 直连失败改走代理的回退。</li><li>失败由 <code>completion_policy</code> 决策，retry/auto-next 经过 Device arbiter，并由 <code>PlaybackTaskRegistry</code> 持有。</li><li><code>_bump_play_session()</code> 不得取消当前正在执行导航的 task 自身。</li><li>所有延迟回调在执行前必须校验 session ID 与 LifecycleToken，旧 session 回调直接丢弃。</li></ul><hr><h2 id="_6-api-与状态确认" tabindex="-1">6. API 与状态确认 <a class="header-anchor" href="#_6-api-与状态确认" aria-label="Permalink to &quot;6. API 与状态确认&quot;">​</a></h2><p><code>POST /api/v1/play</code> 的 Coordinator 可返回 deferred accepted receipt：<code>accepted=true</code>、<code>started=null</code>。这表示命令已进入 Mina/Device arbiter 链路，不代表物理播放已开始。Stop 的 <code>accepted</code> 也只表示 stop 命令被接受；物理完成须观察 runtime phase=<code>STOPPED</code>。状态查询是纯读，不得创建 task、取消 task、调用 Mina 或隐式修复状态。</p><p>控制接口成功只表示动作已进入控制链，不表示音箱已完成切歌。</p><p>调用方必须通过以下任一状态通道确认结果：</p><ul><li><code>GET /api/v1/player/state</code></li><li><code>GET /api/v1/player/stream</code></li></ul><p>确认条件：</p><ul><li><code>play_session_id</code> 已变化；</li><li><code>transport_state == &quot;playing&quot;</code>；</li><li><code>context.id</code> 仍是原歌单；</li><li><code>current_index</code> 沿当前队列快照移动；</li><li><code>track.entity_id</code> 与新索引对应。</li></ul><p>远端小米音箱控制可能受认证刷新、云端限流和设备响应延迟影响。客户端不得因 HTTP 请求耗时较长而自行重发 <code>/play</code>，否则会替换当前 session。</p><hr><h2 id="_7-回归门禁" tabindex="-1">7. 回归门禁 <a class="header-anchor" href="#_7-回归门禁" aria-label="Permalink to &quot;7. 回归门禁&quot;">​</a></h2><p>随机播放控制改动至少验证：</p><ol><li>固定快照 <code>[C, A, D, B]</code>，从 <code>C</code> 开始：next → <code>A</code>，next → <code>D</code>，previous → <code>A</code>。</li><li>整段操作只建立一次外部播放 session，只洗牌一次。</li><li>next/previous 不调用 <code>PlaybackFacade.play()</code>、source resolve 或 playlist bootstrap。</li><li><code>context.id</code> 与队列快照保持不变。</li><li><code>device.play_type</code> 不因单次 <code>options.shuffle=true</code> 改变。</li><li>WebUI next/previous 只发送一个 control 请求。</li><li>WebUI 首页及其引用的实际 JS/CSS bundle 均返回 200。</li><li>日志中不出现同曲破坏性重播、epoch 级假 offset 或明文凭据。</li></ol><hr><h2 id="_8-外部设计参照" tabindex="-1">8. 外部设计参照 <a class="header-anchor" href="#_8-外部设计参照" aria-label="Permalink to &quot;8. 外部设计参照&quot;">​</a></h2><p>控制模型参考了公开播放器的通用原则：UI 只发送意图、队列由单一控制器持有、next 与播放结束汇入同一导航入口、随机模式维护稳定队列。外部项目仅用于验证控制原则，不复制其代码。</p><p>xiaomusic-core 与本地播放器的关键差异是：播放设备位于远端，状态存在延迟且可能被语音、蓝牙或其他客户端抢占。因此本项目保留本地 timer、session ID、有限状态宽限和投递确认机制。</p><hr><h2 id="_9-devicecommandarbiter-与-preplay-stop-现行规则" tabindex="-1">9. DeviceCommandArbiter 与 preplay stop 现行规则 <a class="header-anchor" href="#_9-devicecommandarbiter-与-preplay-stop-现行规则" aria-label="Permalink to &quot;9. DeviceCommandArbiter 与 preplay stop 现行规则&quot;">​</a></h2><ul><li><code>DeviceCommandArbiter</code> 的 per-device 单 worker 中，active intent 即事务 owner；物理 stop 不脱离该 executor。</li><li>preplay group stop 不可取消，必须 await <code>group_force_stop_xiaoai()</code> 到 exact-terminal，并显式判定 <code>_group_stop_result_succeeded</code>；慢只影响后续命令延迟，不改变正确性。</li><li>stop 返回失败或 unknown 时，当前 play/AUTO_NEXT 不得 dispatch；普通 <code>_playmusic</code> 会捕获 stop 异常并将 runtime 置为 <code>FAILED</code> 后返回 <code>False</code>，未吞异常的 executor 路径则由 arbiter 记录 executor failure；最新 pending/after-barrier intent 按现有 generation/token 规则继续处理。</li><li>若 stop RPC 永久挂死，active owner 保持 fail-closed，后续 intent 不越过它；这是已知运维风险，只能通过 transport/设备侧恢复处理，不以软超时放行。</li><li>外部 URL 与本地播放共用同一 exact stop 与 stale-token fence。facade probe 只观测；failure 仍是 unknown，不执行 physical-confirm、stop recovery 或放行逻辑，probe response 也不再提供 group-stop recovery extra 字段。</li><li>preplay stop 失败时本曲不下发，交给统一失败处理（<code>_handle_play_failure</code>）按重试/下一首策略继续；此时不以“音箱仍在播放”为由跳过重试（那只是上一首或单项队列在循环）。</li><li>暂停/恢复不在产品范围内，已于 2026-11-23 删除（接口、<code>PlaybackPhase.PAUSED</code>、arbiter 的 PAUSE/RESUME 意图）。停止仍是唯一的屏障命令。</li></ul><h2 id="_10-相关文档" tabindex="-1">10. 相关文档 <a class="header-anchor" href="#_10-相关文档" aria-label="Permalink to &quot;10. 相关文档&quot;">​</a></h2><ul><li><a href="./../api/api_v1_spec.html"><code>../api/api_v1_spec.md</code></a></li><li><a href="./../adr/0004-state-authority.html"><code>../adr/0004-state-authority.md</code></a></li><li><a href="./state-authority.html"><code>state-authority.md</code></a></li><li><a href="./system_overview.html"><code>system_overview.md</code></a></li><li><a href="https://github.com/Akari787/xiaomusic-core/blob/main/tests/manual_smoke.md" target="_blank" rel="noreferrer"><code>../../tests/manual_smoke.md</code></a></li></ul>`,54)]))}const k=a(o,[["render",l]]);export{u as __pageData,k as default};
